from . import T

S = "Tahap 1 · Dasar statistika"

T("dasar-jenis-data", "Jenis Data dan Variabel",
  "Mengenal skala data dan peran variabel, karena inilah yang menentukan metode analisis.",
  ["Membedakan data nominal, ordinal, interval, dan rasio", "Membedakan variabel respon, perlakuan/faktor, dan kovariat", "Memilih keluarga metode dari jenis data"],
  ["Setiap kolom pada tabel data punya skala ukur. Skala menentukan operasi apa yang masuk akal: rata-rata hanya bermakna untuk data numerik, sedangkan data kategori hanya bisa dihitung frekuensinya.",
   "Selain skala, tentukan peran tiap kolom. Variabel respon (Y) adalah yang diukur sebagai hasil. Faktor atau perlakuan adalah yang dikendalikan peneliti, biasanya kategori seperti varietas atau dosis. Kovariat adalah variabel numerik pendamping yang ikut memengaruhi Y tetapi bukan fokus utama.",
   "Aturan praktis: respon numerik kontinu dengan prediktor kategori mengarah ke ANOVA dan rancangan percobaan; respon numerik dengan prediktor numerik mengarah ke regresi; respon biner atau cacahan mengarah ke regresi logistik atau Poisson."],
  [("Nominal", "kategori tanpa urutan (jenis kelamin, varietas)"), ("Ordinal", "kategori berurutan (rendah < sedang < tinggi)"),
   ("Interval", "numerik, selisih bermakna, nol sembarang (suhu °C)"), ("Rasio", "numerik dengan nol mutlak (bobot, tinggi, hasil panen)")],
  ["Tulis pertanyaan penelitian dalam satu kalimat.", "Tandai kolom mana yang respon, mana faktor, mana kovariat.", "Tentukan skala tiap kolom.", "Cocokkan dengan keluarga metode di Panduan Metode."],
  ["Pada kalkulator, kolom numerik muncul di pilihan respon, kolom teks muncul di pilihan faktor.", "Kolom kode angka seperti 1, 2, 3 untuk kategori terbaca numerik; ubah menjadi teks (A, B, C) agar dikenali sebagai faktor."],
  ["Menganggap kode kategori (1, 2, 3) sebagai angka sungguhan.", "Memakai rata-rata untuk data ordinal tanpa pertimbangan.", "Mencampur peran kolom: faktor dipakai sebagai respon."],
  "Buka salah satu metode di kalkulator, muat data contoh, lalu tunjuk sendiri mana respon, mana faktor, dan mana kovariat sebelum melihat pilihan kolom yang diisi otomatis.",
  tahap=S, method="rancangan-acak-lengkap")

T("dasar-statistik-deskriptif", "Statistik Deskriptif",
  "Meringkas data dengan ukuran pemusatan dan penyebaran sebelum analisis lanjutan.",
  ["Menghitung rata-rata, simpangan baku, galat baku, dan koefisien keragaman", "Membedakan simpangan baku (SD) dan galat baku (SE)", "Membaca tabel deskriptif pada hasil kalkulator"],
  ["Ukuran pemusatan menjawab 'di mana pusat data': rata-rata (mean), median, modus. Ukuran penyebaran menjawab 'seberapa menyebar': ragam, simpangan baku, rentang.",
   "SD menggambarkan sebaran data individual. SE menggambarkan ketelitian rata-rata sampel sebagai penduga rata-rata populasi, sehingga makin kecil bila ulangan bertambah. Koefisien keragaman (KK) menyatakan SD relatif terhadap rata-rata dalam persen, berguna membandingkan keragaman antar variabel berbeda satuan."],
  [("Rata-rata", "x̄ = Σx / n"), ("Ragam", "s² = Σ(x − x̄)² / (n − 1)"), ("Simpangan baku", "s = √s²"), ("Galat baku", "SE = s / √n"), ("KK", "KK = (s / x̄) × 100%")],
  ["Urutkan dan lihat data; periksa nilai ekstrem.", "Hitung rata-rata dan SD per kelompok.", "Hitung SE bila hendak menampilkan batang galat pada grafik.", "Laporkan n, rata-rata, dan SD (atau SE) bersama-sama."],
  ["Contoh data 4, 6, 8, 10, 12: rata-rata 8; ragam (16+4+0+4+16)/4 = 10; SD = 3,162; SE = 3,162/√5 = 1,414; KK = 39,5%.", "Pada hasil kalkulator, kolom N, Rata-rata, SD, SE, Min, Maks adalah statistik deskriptif per perlakuan."],
  ["Mencampur SD dan SE tanpa menyebutkan mana yang dipakai pada grafik.", "Memakai KK pada data yang rata-ratanya mendekati nol.", "Mengabaikan pencilan yang menggeser rata-rata."],
  "Jalankan RAL dengan data contoh. Lihat tabel deskriptif, lalu ganti batang galat pada grafik antara SD dan SE dan perhatikan perubahan panjangnya.",
  pra=["dasar-jenis-data"], tahap=S, method="rancangan-acak-lengkap")

T("dasar-distribusi-normal", "Distribusi Normal",
  "Bentuk lonceng yang menjadi dasar sebagian besar uji parametrik.",
  ["Memahami ciri distribusi normal dan nilai z", "Mengetahui mengapa normalitas penting", "Membaca plot Q-Q dan uji normalitas"],
  ["Distribusi normal berbentuk lonceng simetris dengan dua parameter: rata-rata μ dan simpangan baku σ. Sekitar 68% data berada dalam μ ± 1σ, 95% dalam μ ± 2σ, dan 99,7% dalam μ ± 3σ.",
   "Nilai baku z menyatakan seberapa jauh suatu nilai dari rata-rata dalam satuan simpangan baku. Dengan z kita dapat menghitung peluang dari tabel normal baku.",
   "Teorema limit pusat menyatakan rata-rata sampel cenderung normal walau data asalnya tidak, asalkan sampel cukup besar. Karena itu uji t dan ANOVA relatif tahan terhadap penyimpangan normalitas ringan, tetapi tidak terhadap pencilan berat atau sampel sangat kecil."],
  [("Nilai baku", "z = (x − μ) / σ"), ("Contoh", "x = 85, μ = 70, σ = 10 → z = 1,5; peluang di bawahnya ≈ 0,933")],
  ["Gambar histogram atau plot Q-Q residual.", "Jalankan uji normalitas (Shapiro-Wilk untuk sampel kecil-sedang).", "Bila menyimpang berat, pertimbangkan transformasi atau metode nonparametrik/robust."],
  ["Plot Q-Q: titik mengikuti garis diagonal berarti normal; lengkung S atau ekor melenceng berarti tidak normal.", "Uji Shapiro-Wilk: P > α berarti tidak ada bukti menyimpang dari normal.", "Normalitas diperiksa pada residual model, bukan pada data mentah seluruh kelompok digabung."],
  ["Menguji normalitas data mentah padahal modelnya punya beberapa kelompok.", "Mengandalkan uji formal saja pada sampel sangat besar (hampir selalu 'nyata') atau sangat kecil (kurang bertenaga).", "Menganggap 'tidak nyata' berarti 'pasti normal'."],
  "Jalankan Diagnostik Regresi di kalkulator, buka tab grafik residual dan uji asumsi, lalu cocokkan bentuk plot Q-Q dengan hasil uji Shapiro-Wilk.",
  pra=["dasar-statistik-deskriptif"], tahap=S, method="diagnostik-regresi-tanpa-intersep")

T("dasar-uji-hipotesis", "Uji Hipotesis dan P-value",
  "Logika pengambilan keputusan statistik: hipotesis, statistik uji, P-value, dan taraf nyata.",
  ["Menyusun H₀ dan H₁", "Menafsirkan P-value dan taraf nyata α", "Memahami galat tipe I, galat tipe II, dan kuasa uji"],
  ["Uji hipotesis membandingkan dua pernyataan. H₀ (hipotesis nol) menyatakan tidak ada efek atau perbedaan; H₁ menyatakan ada. Kita menghitung statistik uji dari data, lalu bertanya: bila H₀ benar, seberapa jarang hasil sejauh ini muncul?",
   "Jawaban itu adalah P-value. Bila P ≤ α (umumnya 0,05), H₀ ditolak dan hasilnya disebut nyata. P-value bukan peluang H₀ benar, dan bukan ukuran besarnya efek.",
   "Galat tipe I adalah menolak H₀ yang benar (peluangnya α). Galat tipe II adalah gagal menolak H₀ yang salah (peluangnya β). Kuasa uji = 1 − β, naik bila ulangan lebih banyak, efek lebih besar, atau galat lebih kecil."],
  [("Uji t satu sampel", "t = (x̄ − μ₀) / (s / √n), db = n − 1"), ("Contoh", "n = 25, x̄ = 52, μ₀ = 50, s = 5 → t = 2,0; db = 24; P (dua arah) ≈ 0,057 → tidak nyata pada α = 0,05"),
   ("Penanda pada tabel", "** P < 0,01 · * P < 0,05 · tn P ≥ 0,05")],
  ["Rumuskan H₀ dan H₁.", "Tetapkan α sebelum melihat data.", "Hitung statistik uji dan P-value.", "Putuskan, lalu laporkan besar efek dan selang kepercayaan, bukan hanya 'nyata'."],
  ["Pada tabel ANOVA kalkulator, kolom P-value dan tanda ** / * / tn adalah hasil keputusan ini.", "P = 0,057 dan P = 0,049 tidak berbeda bermakna secara praktis; jangan memperlakukan 0,05 sebagai tembok."],
  ["Mengartikan P = 0,03 sebagai 'peluang H₀ benar 3%'.", "Mengubah α setelah melihat hasil.", "Menyimpulkan 'tidak ada efek' dari hasil tidak nyata pada sampel kecil."],
  "Jalankan RAL dengan data contoh, ganti taraf nyata α dari 0,01 ke 0,05 ke 0,10, dan amati bagaimana tanda signifikansi pada tabel ANOVA berubah.",
  pra=["dasar-distribusi-normal"], tahap=S, method="rancangan-acak-lengkap")

T("dasar-selang-kepercayaan", "Selang Kepercayaan",
  "Rentang nilai yang masuk akal bagi parameter populasi, lebih informatif daripada P-value saja.",
  ["Menghitung selang kepercayaan rata-rata", "Menafsirkan tingkat kepercayaan dengan benar", "Membedakan selang kepercayaan dan selang prediksi"],
  ["Selang kepercayaan (CI) 95% adalah rentang yang dibangun dengan prosedur yang, bila diulang berkali-kali, memuat parameter sebenarnya pada 95% pengulangan. Selang yang sempit berarti penduga teliti.",
   "Selang kepercayaan berbicara tentang rata-rata. Selang prediksi (PI) berbicara tentang satu pengamatan baru, sehingga selalu lebih lebar karena memuat keragaman individu."],
  [("CI rata-rata", "x̄ ± t(α/2; n−1) · s/√n"), ("Contoh", "x̄ = 52, s = 5, n = 25: 52 ± 2,064 × 1 = [49,94 ; 54,06]"), ("Lebar", "mengecil bila n naik atau s turun")],
  ["Hitung rata-rata dan galat baku.", "Ambil nilai t dari tabel dengan db = n − 1.", "Bentuk batas bawah dan atas.", "Periksa apakah nilai acuan (misalnya 50) berada di dalam selang."],
  ["Bila selang memuat nilai hipotesis nol, uji dua arah pada α yang bersesuaian tidak nyata, dan sebaliknya.", "Pada Kalkulator Prediksi regresi, CI untuk rata-rata Y dan PI untuk pengamatan baru ditampilkan berdampingan."],
  ["Menyebut 'peluang parameter berada di selang ini 95%'.", "Memakai CI untuk memprediksi satu pengamatan.", "Membandingkan dua rata-rata hanya dengan melihat tumpang tindih selang."],
  "Jalankan Regresi Linear, buka tab Prediksi, masukkan nilai X di tengah rentang data lalu di luar rentang, dan bandingkan lebar CI dan PI pada kedua kasus.",
  pra=["dasar-uji-hipotesis"], tahap=S, method="regresi-linear-sederhana-berganda")

T("dasar-asumsi-residual", "Asumsi Model dan Residual",
  "Syarat agar hasil uji dapat dipercaya, dan cara memeriksanya lewat residual.",
  ["Mengenal empat asumsi: normalitas, homogenitas ragam, independensi, linearitas", "Membaca plot residual", "Memilih tindakan bila asumsi dilanggar"],
  ["Model statistik menulis pengamatan sebagai bagian yang dijelaskan model ditambah galat. Residual e = y − ŷ adalah perkiraan galat. Asumsi yang dibuat pada galat: berdistribusi normal, ragam sama di semua kelompok atau nilai prediksi, saling bebas, dan (pada regresi) hubungan berbentuk linear.",
   "Pelanggaran ringan sering tidak berbahaya, terutama pada data seimbang. Pelanggaran berat mengubah P-value dan selang kepercayaan sehingga kesimpulan menyesatkan."],
  [("Residual", "eᵢ = yᵢ − ŷᵢ"), ("Normalitas", "Shapiro-Wilk, plot Q-Q"), ("Homogenitas ragam", "Levene, Bartlett, Breusch-Pagan"), ("Independensi", "Durbin-Watson, pengacakan yang benar")],
  ["Jalankan analisis dan simpan residual.", "Lihat plot residual vs prediksi: titik harus tersebar acak tanpa pola corong atau lengkung.", "Lihat plot Q-Q dan uji formal.", "Bila melanggar: transformasi (log, akar), metode robust, nonparametrik, atau model lain (GLM)."],
  ["Pola corong pada residual vs prediksi menandakan ragam tidak homogen.", "Pola lengkung menandakan hubungan tidak linear: tambah suku kuadrat atau pakai metode nonlinear.", "Pola berulang berurutan menandakan autokorelasi: pertimbangkan model deret waktu."],
  ["Hanya mengandalkan uji formal tanpa melihat grafik.", "Menghapus data agar 'lolos asumsi'.", "Mengabaikan independensi, padahal pengacakan yang salah tidak bisa diperbaiki secara statistik."],
  "Jalankan Diagnostik Regresi dengan data contoh dan baca tab Uji Asumsi dan grafik residual. Tentukan asumsi mana yang terpenuhi dan mana yang meragukan.",
  pra=["dasar-distribusi-normal"], tahap=S, method="diagnostik-regresi-tanpa-intersep")

T("dasar-prinsip-rancangan", "Prinsip Rancangan Percobaan",
  "Replikasi, pengacakan, dan kontrol lokal: tiga pilar yang membuat kesimpulan sebab-akibat sah.",
  ["Mendefinisikan satuan percobaan, faktor, taraf, dan perlakuan", "Menerapkan replikasi, pengacakan, dan pengelompokan", "Menghindari pseudoreplikasi"],
  ["Percobaan memberi perlakuan pada satuan percobaan, lalu mengukur respon. Faktor adalah peubah yang dibandingkan (misalnya dosis pupuk), taraf adalah nilai-nilainya (0, 50, 100 kg), dan perlakuan adalah kombinasi taraf.",
   "Replikasi (ulangan) memberi taksiran galat percobaan dan menaikkan ketelitian. Pengacakan menghilangkan bias sistematik dan membenarkan uji statistik. Kontrol lokal, yaitu pengelompokan satuan yang mirip ke dalam blok, memisahkan keragaman yang diketahui dari galat.",
   "Pseudoreplikasi terjadi saat pengamatan berulang pada satu satuan percobaan dianggap ulangan independen, misalnya 10 daun dari satu pot dianggap 10 ulangan. Ulangan sejati adalah satuan percobaan yang diberi perlakuan secara terpisah."],
  [("Model dasar", "Yᵢⱼ = μ + τᵢ + εᵢⱼ"), ("Derajat bebas", "perlakuan t − 1; galat t(r − 1) pada rancangan acak lengkap")],
  ["Tentukan satuan percobaan dan tujuan.", "Tentukan faktor, taraf, dan jumlah ulangan.", "Pilih rancangan: homogen → acak lengkap; ada satu sumber keragaman → kelompok; dua sumber → bujur sangkar Latin.", "Acak penempatan perlakuan, lalu catat data."],
  ["Rancangan yang cocok terlihat dari struktur data: kolom perlakuan, kolom kelompok bila ada, dan kolom respon.", "Jumlah ulangan menentukan derajat bebas galat; ulangan terlalu sedikit membuat uji kurang bertenaga."],
  ["Tidak mengacak karena 'lebih mudah dikerjakan berurutan'.", "Memakai blok yang tidak berkaitan dengan keragaman respon.", "Pseudoreplikasi."],
  "Buka Panduan Metode, pilih situasi percobaan yang paling mirip dengan penelitian Anda, lalu buka metode yang disarankan.",
  pra=["dasar-statistik-deskriptif"], tahap=S, method="rancangan-acak-lengkap")

T("dasar-anova", "Konsep Analisis Ragam (ANOVA)",
  "Memecah keragaman total menjadi bagian perlakuan dan galat, lalu mengujinya dengan F.",
  ["Memahami penguraian jumlah kuadrat", "Menghitung F dan membaca tabel ANOVA", "Mengetahui kapan ANOVA dipakai"],
  ["ANOVA menguji apakah rata-rata beberapa kelompok sama. Idenya: keragaman total di data dipecah menjadi keragaman antar kelompok (karena perlakuan) dan keragaman dalam kelompok (galat). Bila keragaman antar kelompok jauh lebih besar daripada galat, perlakuan berpengaruh.",
   "Perbandingan itu dibuat dengan membagi jumlah kuadrat dengan derajat bebasnya, menghasilkan kuadrat tengah (KT). Statistik F = KT perlakuan / KT galat, dibandingkan dengan sebaran F."],
  [("Penguraian", "JK total = JK perlakuan + JK galat"), ("Kuadrat tengah", "KT = JK / db"), ("Statistik uji", "F = KT perlakuan / KT galat"),
   ("Contoh", "Kelompok A: 4,5,6; B: 6,7,8; C: 8,9,10. JKP = 24, JKG = 6, db = 2 dan 6, KTP = 12, KTG = 1, F = 12, P = 0,008 (**)")],
  ["Hitung rata-rata umum dan rata-rata tiap kelompok.", "Hitung JK perlakuan dan JK galat.", "Bagi dengan db untuk mendapat KT, lalu hitung F.", "Bila F nyata, lanjutkan dengan uji lanjut."],
  ["F besar dan P kecil: setidaknya satu kelompok berbeda dari yang lain; ANOVA tidak menyebut kelompok mana.", "KK pada tabel menunjukkan ketelitian percobaan; makin kecil makin baik.", "Dengan F tidak nyata, uji lanjut umumnya tidak dilakukan."],
  ["Mengira F nyata berarti semua kelompok berbeda.", "Memakai ANOVA pada data yang melanggar asumsi berat tanpa transformasi.", "Menggunakan banyak uji t, bukan ANOVA, sehingga galat tipe I membengkak."],
  "Jalankan RAL dengan data contoh. Cocokkan JK, db, KT, dan F pada tabel dengan rumus di atas, lalu ubah satu nilai data dan perhatikan perubahan F.",
  pra=["dasar-uji-hipotesis", "dasar-prinsip-rancangan"], tahap=S, method="rancangan-acak-lengkap")

T("dasar-uji-lanjut", "Uji Lanjut (Post-hoc)",
  "Setelah F nyata: kelompok mana yang berbeda, dan bagaimana menjaga galat tipe I.",
  ["Mengenal BNT, DMRT, Tukey, Scheffé, dan Dunnett", "Memilih uji lanjut sesuai tujuan", "Membaca notasi huruf"],
  ["Uji lanjut membandingkan rata-rata berpasangan setelah ANOVA nyata. Makin banyak pembandingan, makin besar peluang menemukan 'perbedaan' semu. Uji yang ketat mengendalikan galat tipe I seluruh keluarga pembandingan, uji yang longgar lebih berdaya tetapi lebih berisiko.",
   "Urutan dari yang paling longgar ke paling ketat kira-kira: BNT (LSD), DMRT (Duncan), Tukey (BNJ), Scheffé. Dunnett khusus membandingkan semua perlakuan terhadap satu kontrol."],
  [("BNT", "BNT = t(α/2; db galat) · √(2·KTG / r)"), ("Contoh", "KTG = 1, r = 3, db = 6: BNT = 2,447 × 0,816 = 2,00; selisih rata-rata A dan B = 2 → batas nyata"), ("Notasi huruf", "rata-rata dengan huruf sama tidak berbeda nyata")],
  ["Lakukan hanya bila uji F nyata.", "Pilih uji sesuai tujuan: semua pasangan → Tukey; terhadap kontrol → Dunnett; eksplorasi → BNT atau DMRT.", "Urutkan rata-rata, beri huruf.", "Laporkan uji yang dipakai."],
  ["Pada kalkulator, mengganti uji lanjut langsung menghitung ulang huruf dan tabel perbandingan.", "Huruf yang sama = tidak berbeda nyata; huruf berbeda = berbeda nyata pada α yang dipilih."],
  ["Melakukan BNT pada banyak perlakuan tanpa mengakui risiko galat tipe I.", "Memilih uji yang memberi hasil 'terbaik'.", "Memakai uji lanjut ketika F tidak nyata."],
  "Jalankan RAL dengan data contoh, lalu ganti uji lanjut dari BNT ke Tukey dan Scheffé. Catat apakah ada pasangan yang hurufnya berubah dan jelaskan kenapa.",
  pra=["dasar-anova"], tahap=S, method="rancangan-acak-lengkap")

T("dasar-korelasi", "Korelasi",
  "Mengukur kekuatan dan arah hubungan linear dua variabel numerik.",
  ["Menghitung dan menafsirkan koefisien korelasi r", "Membedakan korelasi dan kausalitas", "Menghubungkan r dengan R² regresi"],
  ["Koefisien korelasi Pearson r berkisar −1 sampai +1. Tanda menunjukkan arah, nilai mutlak menunjukkan kekuatan hubungan linear. Nilai 0 berarti tidak ada hubungan linear, bukan tidak ada hubungan apa pun.",
   "Pada regresi linear sederhana, R² = r². Artinya r² adalah proporsi keragaman Y yang dijelaskan oleh X. Korelasi tinggi tidak membuktikan sebab-akibat, karena bisa ada variabel ketiga yang memengaruhi keduanya."],
  [("Korelasi", "r = Σ(x − x̄)(y − ȳ) / √[Σ(x − x̄)² · Σ(y − ȳ)²]"), ("Contoh", "x = 1..5, y = 2,4,5,4,5 → r = 6/√60 = 0,775; r² = 0,60")],
  ["Gambar diagram pencar terlebih dahulu.", "Hitung r dan ujinya.", "Periksa pencilan yang dapat mengubah r drastis.", "Bila tujuan memprediksi, lanjut ke regresi."],
  ["Heatmap korelasi pada hasil regresi memperlihatkan pasangan variabel yang berkorelasi kuat; pasangan X yang korelasinya sangat tinggi berpotensi multikolinearitas.", "Pada n kecil, r yang tampak besar bisa tidak nyata: r = 0,775 dengan n = 5 memiliki P = 0,12."],
  ["Menyimpulkan sebab-akibat dari korelasi.", "Memakai r untuk hubungan yang melengkung.", "Mengabaikan pencilan atau rentang data yang sempit."],
  "Jalankan Regresi Linear dengan data contoh, lihat heatmap korelasi dan diagram pencar, lalu bandingkan R² dengan kuadrat korelasi X dan Y.",
  pra=["dasar-statistik-deskriptif"], tahap=S, method="regresi-linear-sederhana-berganda")
